export function buildTaxesRecordsSchedule(startISO = null) {
  return buildScheduleFor(TAXES_RECORDS_MODULES, startISO, TAXES_RECORDS_META.cadenceDays);
}

export function taxesRecordsProgressSummary(progress = {}) {
  return progressSummaryFor(TAXES_RECORDS_MODULES, progress);
}

export function exportTaxesRecordsCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: TAXES_RECORDS_META,
    modules: buildTaxesRecordsSchedule(startISO),
    sessionFlow: TAXES_RECORDS_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function taxesRecordsRefs() {
  const seen = new Set();
  for (const m of TAXES_RECORDS_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((TAXES_RECORDS_META.wordFirst && TAXES_RECORDS_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

